import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

export default function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await login(email, password);
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.error || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-vh-100 d-flex align-items-center justify-content-center" style={{ background: 'linear-gradient(135deg,#4f46e5,#7c3aed)' }}>
      <div className="card card-mw shadow p-4" style={{ width: '100%', maxWidth: 420 }}>
        <h3 className="text-center mb-1">MindWatch AI</h3>
        <p className="text-center text-muted mb-4">Mental Health Monitoring System</p>
        {error && <div className="alert alert-danger">{error}</div>}
        <form onSubmit={handleSubmit}>
          <div className="mb-3">
            <label className="form-label">Email</label>
            <input type="email" className="form-control" value={email} onChange={(e) => setEmail(e.target.value)} required />
          </div>
          <div className="mb-3">
            <label className="form-label">Password</label>
            <input type="password" className="form-control" value={password} onChange={(e) => setPassword(e.target.value)} required />
          </div>
          <button className="btn btn-primary w-100" disabled={loading}>{loading ? 'Signing in...' : 'Login'}</button>
        </form>
        <div className="text-center mt-3">
          <Link to="/forgot-password">Forgot password?</Link> · <Link to="/register">Register</Link>
        </div>
        <p className="text-muted small mt-3 mb-0 text-center">Demo admin: admin@mindwatch.ai / admin123</p>
      </div>
    </div>
  );
}
